using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
public static class GrassPrefabBuild {
 public static string Run() {
 if(EditorApplication.isCompiling || EditorApplication.isPlaying) throw new Exception("Editor must be idle in Edit mode.");
 var before = Enumerable.Range(0, UnityEngine.SceneManagement.SceneManager.sceneCount).Select(i=>UnityEngine.SceneManagement.SceneManager.GetSceneAt(i)).Select(s=>s.path+":"+s.isDirty).ToArray();
 var src=new Texture2D(2,2,TextureFormat.RGBA32,false);
 if(!src.LoadImage(File.ReadAllBytes("output/imagegen/foreground-grass-v2.png"))) throw new Exception("PNG failed");
 var pixels=src.GetPixels32();
 var entries=new List<Tuple<string,RectInt>>();
 // Source row names and regions, coordinates use Unity bottom-left origin.
 int[,] regions={{0,450,560,src.height},{560,450,1130,src.height},{1130,450,src.width,src.height},{0,0,560,450},{560,0,1210,450},{1210,0,src.width,450}};
 string[] forms={"SmallPetalTuft","FlowerFan","WideTuft","LeaningPetalTuft","LongGrassPatch","FlowerTuft"};
 for(int i=0;i<6;i++){
 int minX=src.width,minY=src.height,maxX=-1,maxY=-1;
 for(int y=regions[i,1];y<regions[i,3];y++)for(int x=regions[i,0];x<regions[i,2];x++){
 if(pixels[y*src.width+x].a<8)continue;
 minX=Math.Min(minX,x);minY=Math.Min(minY,y);maxX=Math.Max(maxX,x);maxY=Math.Max(maxY,y);
 }
 if(maxX<minX)throw new Exception("Empty region "+i);
 entries.Add(Tuple.Create(forms[i],new RectInt(minX,minY,maxX-minX+1,maxY-minY+1)));
 }
 entries=entries.OrderByDescending(e=>e.Item2.width*e.Item2.height).ToList();
 string art="Assets/Art/Environment/ForegroundGrass";
 string pref="Assets/Prefabs/Foreground/Grass";
 foreach(string folder in new[]{art,pref}) { string p="Assets"; foreach(string part in folder.Substring(7).Split('/')){string next=p+"/"+part;if(!AssetDatabase.IsValidFolder(next))AssetDatabase.CreateFolder(p,part);p=next;} }
 foreach(var e in entries.Select((v,i)=>new{v,i})) {
 string name="ForegroundGrass_"+(e.i+1).ToString("D2")+"_"+e.v.Item1;
 if(File.Exists(art+"/"+name+".png")||File.Exists(pref+"/"+name+".prefab"))throw new Exception("Already exists: "+name);
 }
 var report=new List<string>();
 for(int i=0;i<entries.Count;i++){
 var entry=entries[i];var r=entry.Item2;
 string name="ForegroundGrass_"+(i+1).ToString("D2")+"_"+entry.Item1;
 string path=art+"/"+name+".png";
 var crop=new Texture2D(r.width,r.height,TextureFormat.RGBA32,false);
 crop.SetPixels(src.GetPixels(r.x,r.y,r.width,r.height));crop.Apply();
 File.WriteAllBytes(path,crop.EncodeToPNG());UnityEngine.Object.DestroyImmediate(crop);
 AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);
 var imp=(TextureImporter)AssetImporter.GetAtPath(path);
 imp.textureType=TextureImporterType.Sprite; imp.spriteImportMode=SpriteImportMode.Single;
 imp.spritePixelsPerUnit=400;imp.filterMode=FilterMode.Point;imp.mipmapEnabled=false;
 imp.textureCompression=TextureImporterCompression.Uncompressed;imp.alphaIsTransparency=true;imp.wrapMode=TextureWrapMode.Clamp;imp.npotScale=TextureImporterNPOTScale.None;imp.maxTextureSize=2048;
 var settings=new TextureImporterSettings();imp.ReadTextureSettings(settings);settings.spriteAlignment=(int)SpriteAlignment.BottomCenter;settings.spritePivot=new Vector2(.5f,0);settings.spriteMeshType=SpriteMeshType.FullRect;imp.SetTextureSettings(settings);imp.SaveAndReimport();
 var go=EditorUtility.CreateGameObjectWithHideFlags(name,HideFlags.HideAndDontSave,typeof(SpriteRenderer));
 try{
 var sr=go.GetComponent<SpriteRenderer>();sr.sprite=AssetDatabase.LoadAssetAtPath<Sprite>(path);
 var fg=go.AddComponent<ForegroundElement>();var so=new SerializedObject(fg);
 so.FindProperty("tint").colorValue=Color.white;so.FindProperty("movement").enumValueIndex=0;
 so.FindProperty("sortingOrder").intValue=30;so.FindProperty("fadeWhenPlayerCovered").boolValue=false;
 so.ApplyModifiedPropertiesWithoutUndo();fg.ApplySettings();
 go.hideFlags=HideFlags.None;
 PrefabUtility.SaveAsPrefabAsset(go,pref+"/"+name+".prefab");
 }finally{UnityEngine.Object.DestroyImmediate(go);}
 var saved=AssetDatabase.LoadAssetAtPath<GameObject>(pref+"/"+name+".prefab");
 var renderer=saved.GetComponent<SpriteRenderer>();
 if(renderer.sprite==null || renderer.sortingOrder!=30 || saved.GetComponent<Collider2D>()!=null)throw new Exception("Validation failed "+name);
 report.Add(name+" | "+r.width+"x"+r.height+"px | "+renderer.sprite.bounds.size.ToString("F3"));
 }
 UnityEngine.Object.DestroyImmediate(src);
 AssetDatabase.SaveAssets();
 var after=Enumerable.Range(0,UnityEngine.SceneManagement.SceneManager.sceneCount).Select(i=>UnityEngine.SceneManagement.SceneManager.GetSceneAt(i)).Select(s=>s.path+":"+s.isDirty).ToArray();
 if(!before.SequenceEqual(after))throw new Exception("Scene dirty state changed");
 return string.Join("\n",report)+"\nScene dirty state preserved. CompilationFailed="+EditorUtility.scriptCompilationFailed;
 }
}
